import{H as e,gt as t,nt as n,rt as r}from"./chunks/framework.C8jghwzB.js";var i=JSON.parse(`{"title":"Features","description":"Explore one-command model installs, hardware-aware runtimes, OpenAI-compatible serving, replication, telemetry, safety, and verified updates.","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://letsinfer.ai/docs/features.html"}],["link",{"rel":"alternate","type":"text/plain","href":"/llms.txt","title":"Let's Infer for language models"}],["link",{"rel":"license","href":"https://github.com/letsinferlabs/letsinfer/blob/main/LICENSE"}],["meta",{"name":"author","content":"Let's Infer"}],["meta",{"name":"robots","content":"index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1"}],["meta",{"property":"og:site_name","content":"Let's Infer"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Features · Let's Infer"}],["meta",{"property":"og:description","content":"Explore one-command model installs, hardware-aware runtimes, OpenAI-compatible serving, replication, telemetry, safety, and verified updates."}],["meta",{"property":"og:url","content":"https://letsinfer.ai/docs/features.html"}],["meta",{"property":"og:image","content":"https://letsinfer.ai/og-image.png"}],["meta",{"property":"og:image:type","content":"image/png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"Let's Infer — local AI, installed like software"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Features · Let's Infer"}],["meta",{"name":"twitter:description","content":"Explore one-command model installs, hardware-aware runtimes, OpenAI-compatible serving, replication, telemetry, safety, and verified updates."}],["meta",{"name":"twitter:image","content":"https://letsinfer.ai/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Let's Infer — local AI, installed like software"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"Organization\\",\\"@id\\":\\"https://letsinfer.ai/#organization\\",\\"name\\":\\"Let's Infer\\",\\"url\\":\\"https://letsinfer.ai/\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://letsinfer.ai/logo.png\\",\\"contentUrl\\":\\"https://letsinfer.ai/logo.png\\",\\"width\\":512,\\"height\\":512},\\"sameAs\\":[\\"https://github.com/letsinferlabs\\"]},{\\"@type\\":\\"WebSite\\",\\"@id\\":\\"https://letsinfer.ai/#website\\",\\"name\\":\\"Let's Infer\\",\\"url\\":\\"https://letsinfer.ai/\\",\\"description\\":\\"Turn your AI hardware into one reliable inference service.\\",\\"inLanguage\\":\\"en-US\\",\\"publisher\\":{\\"@id\\":\\"https://letsinfer.ai/#organization\\"}},{\\"@type\\":[\\"SoftwareApplication\\",\\"SoftwareSourceCode\\"],\\"@id\\":\\"https://letsinfer.ai/#software\\",\\"name\\":\\"Let's Infer\\",\\"alternateName\\":\\"letsinfer\\",\\"description\\":\\"Open-source, engine-agnostic inference distribution and runtime manager for local AI hardware.\\",\\"url\\":\\"https://letsinfer.ai/\\",\\"codeRepository\\":\\"https://github.com/letsinferlabs/letsinfer\\",\\"downloadUrl\\":\\"https://letsinfer.ai/install.sh\\",\\"license\\":\\"https://github.com/letsinferlabs/letsinfer/blob/main/LICENSE\\",\\"applicationCategory\\":\\"DeveloperApplication\\",\\"operatingSystem\\":\\"Linux, macOS\\",\\"isAccessibleForFree\\":true,\\"publisher\\":{\\"@id\\":\\"https://letsinfer.ai/#organization\\"}},{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://letsinfer.ai/docs/features.html#article\\",\\"headline\\":\\"Features\\",\\"description\\":\\"Explore one-command model installs, hardware-aware runtimes, OpenAI-compatible serving, replication, telemetry, safety, and verified updates.\\",\\"url\\":\\"https://letsinfer.ai/docs/features.html\\",\\"mainEntityOfPage\\":\\"https://letsinfer.ai/docs/features.html\\",\\"inLanguage\\":\\"en-US\\",\\"isPartOf\\":{\\"@id\\":\\"https://letsinfer.ai/#website\\"},\\"about\\":{\\"@id\\":\\"https://letsinfer.ai/#software\\"},\\"author\\":{\\"@id\\":\\"https://letsinfer.ai/#organization\\"},\\"publisher\\":{\\"@id\\":\\"https://letsinfer.ai/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://letsinfer.ai/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Documentation\\",\\"item\\":\\"https://letsinfer.ai/docs/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"Features\\",\\"item\\":\\"https://letsinfer.ai/docs/features.html\\"}]}]}"]]},"headers":[],"relativePath":"docs/features.md","filePath":"docs/features.md"}`),a={name:`docs/features.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to “Features”">​</a></h1><p><a href="./">Back to documentation</a></p><p>Let&#39;s Infer turns local AI hardware into a dependable inference service. You choose a model; Let&#39;s Infer handles the hardware match, exact artifacts, engine, lifecycle, API, safety, telemetry, and updates.</p><h2 id="install-a-model-not-a-deployment-stack" tabindex="-1">Install a model, not a deployment stack <a class="header-anchor" href="#install-a-model-not-a-deployment-stack" aria-label="Permalink to “Install a model, not a deployment stack”">​</a></h2><ul><li><strong>Model-first installation.</strong> Run <code>letsinfer model install MODEL</code>. You never need to choose an engine, locate weights, or write a hardware-specific launch command.</li><li><strong>Automatic hardware matching.</strong> Let&#39;s Infer identifies the local target and selects the fastest qualified runtime from the signed catalog. Use <code>--runtime</code> when you want to pin an exact candidate.</li><li><strong>Exact, deduplicated downloads.</strong> The selected runtime brings its pinned model revision, Engine distribution, adapter, dependencies, and optional sidecars. Content-addressed stores avoid downloading identical content twice.</li><li><strong>Ready means ready.</strong> A normal install starts inference and waits for the API to become usable. Pause and resume are explicit model lifecycle actions.</li><li><strong>One home directory.</strong> Core releases, configuration, secrets, runtime packs, models, benchmark evidence, and rebuildable caches live below <code>$LETSINFER_HOME</code> (normally <code>~/.local/share/letsinfer</code>).</li><li><strong>Auditable storage cleanup.</strong> <code>letsinfer node usage</code> breaks down owned space and can remove only reviewed inactive models, rebuildable caches, and completed benchmark data. Running models and rollback inputs stay protected; a cleaned model is downloaded and verified again on each replica or parallel member before that runtime starts.</li></ul><h2 id="one-stable-api" tabindex="-1">One stable API <a class="header-anchor" href="#one-stable-api" aria-label="Permalink to “One stable API”">​</a></h2><ul><li><strong>OpenAI-compatible gateway.</strong> Every supported engine is served through <code>http://&lt;hostname&gt;.local:8000/v1</code> on your LAN.</li><li><strong>Engine-independent clients.</strong> Changing from SGLang to DwarfStar—or to a future engine—does not change the client endpoint.</li><li><strong>Local discovery.</strong> The main node advertises itself with mDNS, so clients and the macOS controller can find it without a hand-maintained IP address.</li><li><strong>Scoped API keys.</strong> Create, rotate, revoke, expire, and restrict keys by model, tenant, application, request rate, token rate, concurrency, and context policy.</li><li><strong>Admission instead of overload.</strong> The gateway and runtime coordinate connection limits, dynamic admission, memory pressure, and FIFO queueing. By default, a request that can eventually fit waits until capacity becomes available or its client disconnects. A request that can never fit receives a structured error instead of crashing the runtime.</li></ul><h2 id="starts-automatically-recovers-deliberately" tabindex="-1">Starts automatically. Recovers deliberately. <a class="header-anchor" href="#starts-automatically-recovers-deliberately" aria-label="Permalink to “Starts automatically. Recovers deliberately.”">​</a></h2><ul><li><strong>Reboot persistence.</strong> Linux user services restore the node, gateway, Watchdog, recovery controller, and selected runtime after reboot.</li><li><strong>Ordinary crash recovery.</strong> The recovery controller can restart a failed engine and rebind the stable gateway without relying on an unbounded Docker restart loop.</li><li><strong>Safety stays authoritative.</strong> OOM and protection trips remain latched. They are never hidden by an automatic restart; inspect the cause and run <code>letsinfer model recover MODEL</code> when it is safe to continue.</li><li><strong>Atomic lifecycle changes.</strong> Pause, resume, restart, recover, install, update, and rollback use one state model rather than competing scripts.</li><li><strong>Clean uninstall.</strong> <code>letsinfer uninstall</code> previews and confirms removal of the complete Let&#39;s Infer home. <code>--keep-models</code> preserves downloaded weights.</li></ul><h2 id="live-normalized-observability" tabindex="-1">Live, normalized observability <a class="header-anchor" href="#live-normalized-observability" aria-label="Permalink to “Live, normalized observability”">​</a></h2><p><code>letsinfer status</code> is a continuously refreshed view of the whole request path, not a container snapshot. It combines the main and child nodes, hardware, links, every logical model and replica group, gateway, Engine adapters, and Watchdog into one state plane.</p><p>Depending on what the Engine adapter and hardware expose, it shows:</p><ul><li>node, lifecycle, runtime, engine, target, API, and guard state;</li><li>active and queued requests, admission capacity, and live context use;</li><li>aggregate, decode, and prefill throughput, TTFT, and prefix-cache state;</li><li>GPU, unified memory, CPU, NVMe, power, and network activity;</li><li>clocks and GPU, CPU, and NVMe temperatures; and</li><li>bounded recent history without inventing unavailable values.</li></ul><p>Engine-specific metrics enter through the versioned Engine protocol. Core and the UI consume the same normalized meanings, regardless of the engine.</p><p><code>letsinfer topology</code> provides the companion live graph for multi-node systems. It renders the main-and-child membership tree using each child&#39;s authenticated control-network transport, then animates directional host RX/TX measurements for separately verified direct links and shows model groups without exposing a manual link-probe control. Membership changes appear on the next frame, online/offline state follows signed fact freshness, interface changes publish each second, and direct-link evidence refreshes every two seconds.</p><p>Platform network setup is provider-owned rather than embedded in topology or orchestration. The DGX Spark provider prepares NVIDIA-compatible ConnectX link-local profiles, while future hardware adds independent providers behind the same generic boundary. If a verified physical link disappears, Core pauses only engine groups whose immutable plans require that link; unrelated local models, replicas, children, and gateway routes continue serving. Link evidence must be restored before an operator can resume the affected group, so reconnect never causes a silent model restart.</p><h2 id="protection-that-understands-unified-memory" tabindex="-1">Protection that understands unified memory <a class="header-anchor" href="#protection-that-understands-unified-memory" aria-label="Permalink to “Protection that understands unified memory”">​</a></h2><p>Watchdog is an independent, bounded-memory native service. It monitors the exact protected process and its cgroup rather than guessing from a container name. Its safety inputs include:</p><ul><li>process identity, health, exit state, and OOM events;</li><li>available and committed unified memory;</li><li>cgroup memory, swap, and pressure-stall information;</li><li>runtime-declared warning and stop thresholds; and</li><li>GPU, CPU, NVMe, thermal, power, and network telemetry.</li></ul><p>Normal pressure reduces admission and queues new work. A terminal condition trips protection, stops unsafe work, records the evidence, and requires an explicit recovery.</p><h2 id="reproducible-from-model-to-benchmark" tabindex="-1">Reproducible from model to benchmark <a class="header-anchor" href="#reproducible-from-model-to-benchmark" aria-label="Permalink to “Reproducible from model to benchmark”">​</a></h2><ul><li><strong>Signed catalog.</strong> Runtime selection begins from an exact-byte Ed25519- signed catalog.</li><li><strong>Immutable identities.</strong> Runtimes pin the Hugging Face revision, Engine distribution digest and configuration, runtime-pack OCI, tokenizer identity, serving recipe, and qualification evidence.</li><li><strong>Deterministic runtime packs.</strong> The release pipeline builds twice and requires byte-identical output.</li><li><strong>No silent fallback.</strong> Unsupported schemas, changed digests, missing artifacts, and identity drift fail closed.</li><li><strong>Traceable releases.</strong> Source manifests, checksums, package inventories, SBOM attestations, and benchmark identities bind the installed bytes to the reviewed source.</li></ul><h2 id="core-and-runtimes-update-independently" tabindex="-1">Core and runtimes update independently <a class="header-anchor" href="#core-and-runtimes-update-independently" aria-label="Permalink to “Core and runtimes update independently”">​</a></h2><ul><li><code>letsinfer update check</code> checks core and all distinct installed engine-group releases.</li><li><code>letsinfer update core</code> changes Core without silently moving your runtime or model.</li><li><code>letsinfer update model MODEL</code> installs a newer qualified runtime without changing core.</li><li><code>letsinfer model rollback MODEL</code> restores the retained previous runtime.</li></ul><p>Every CLI command can surface a cached update notice. Online checks update one durable update state; transient network failures do not erase the last known result. After a verified handoff, obsolete core payloads are pruned while models and the active rollback target remain intact.</p><h2 id="benchmarks-are-a-product-feature" tabindex="-1">Benchmarks are a product feature <a class="header-anchor" href="#benchmarks-are-a-product-feature" aria-label="Permalink to “Benchmarks are a product feature”">​</a></h2><p><code>letsinfer benchmark run MODEL</code> runs the same model-neutral workload contract for every runtime:</p><ul><li>canonical code and prose prompts at fixed context and concurrency cells;</li><li>exact Engine-rendered token counting;</li><li>a fresh runtime lifecycle and empty prefix state for every measured cell;</li><li>live progress that survives terminal detachment;</li><li>safe cancellation and restoration of the prior inference state; and</li><li>validated JSON with throughput, TTFT, cache state, utilization, clocks, temperatures, memory, NVMe, power, network, and a telemetry timeline.</li></ul><p>Benchmark records are bound to the runtime, model, Engine distribution, target, installation, prompt set, and contract. They are evidence, not a prose claim.</p><h2 id="nodes-replication-controllers-and-exposure" tabindex="-1">Nodes, replication, controllers, and exposure <a class="header-anchor" href="#nodes-replication-controllers-and-exposure" aria-label="Permalink to “Nodes, replication, controllers, and exposure”">​</a></h2><ul><li><strong>One main node.</strong> The main node owns the public gateway, replica placement, keys, audit log, and controller policy.</li><li><strong>Mixed-hardware replication.</strong> Install the same logical model on every compatible node. Each node resolves its own qualified runtime while clients continue using one endpoint.</li><li><strong>Capacity-aware routing.</strong> The gateway selects healthy groups, queues when every replica is full, and retries another group only before streaming.</li><li><strong>Rolling runtime changes.</strong> Upgrade and rollback proceed group by group and restore the exact prior signed release if a replacement fails.</li><li><strong>Secure controller pairing.</strong> Private controller operations use a comparison-code flow, pinned node CA, mTLS identity, and role enforcement.</li><li><strong>Node-level audit.</strong> Mutating CLI and controller actions carry an explicit main, child, or all scope and enter the tamper-evident audit log.</li><li><strong>Optional public inference.</strong> Tailscale Funnel can expose only the inference gateway while private control and Watchdog surfaces remain private.</li></ul><p>Replication reuses independently qualified target runtimes. Distributed TP/PP execution requires a runtime that explicitly qualifies the complete topology; Let&#39;s Infer never reinterprets a single-device benchmark as a parallel result. Core supplies generic allocation, verified connection facts, phased launch, atomic recovery, and one endpoint per complete group. Runtime authors retain full control over ranks, stages, transports, kernels, and engine configuration.</p><h2 id="a-runtime-platform-not-an-engine-fork" tabindex="-1">A runtime platform, not an engine fork <a class="header-anchor" href="#a-runtime-platform-not-an-engine-fork" aria-label="Permalink to “A runtime platform, not an engine fork”">​</a></h2><p>Core owns the stable gateway, lifecycle, catalog, stores, benchmarking, security, and Engine protocol. An Engine distribution contains one engine version and its matching adapter. A runtime candidate can then supply the exact model, target configuration, kernels, patches, sidecars, cache integration, and benchmark evidence.</p><p>This separation lets runtime authors do deep model and kernel work without putting model-specific behavior into core. Engine and runtime releases can move independently whenever the Engine protocol remains compatible.</p><h2 id="native-macos-control" tabindex="-1">Native macOS control <a class="header-anchor" href="#native-macos-control" aria-label="Permalink to “Native macOS control”">​</a></h2><p>The macOS menu-bar controller discovers nearby nodes, securely pairs without SSH, shows topology and live telemetry, controls lifecycle actions according to its role, and manages API keys. It is a true telemetry consumer: it keeps only the bounded window visible in the UI and never persists telemetry history to disk.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next steps”">​</a></h2><ul><li><a href="./getting-started/installation.html">Install Let&#39;s Infer</a></li><li><a href="./reference/cli.html">Use the CLI</a></li><li><a href="./concepts/runtime-packs.html">Understand runtime candidates</a></li><li><a href="./concepts/engine-adapters.html">Develop an Engine distribution</a></li><li><a href="./operations/watchdog.html">Operate Watchdog</a></li><li><a href="https://github.com/letsinferlabs/letsinfer/blob/2dbe913262ca5f75fd4a8685ae55d72fa21890db/benchmarks/README.md" target="_blank" rel="noreferrer">Run benchmarks</a></li><li><a href="https://github.com/letsinferlabs/letsinfer/blob/2dbe913262ca5f75fd4a8685ae55d72fa21890db/apps/macos/README.md" target="_blank" rel="noreferrer">Use the macOS controller</a></li></ul>`,39)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};